/*
 * routines that control user, group, uid and gid caches (for the archive
 * member print routine).
 * IMPORTANT:
 * these routines cache BOTH hits and misses, a major performance improvement
 */

import CMigration
import Darwin

class Cache {

  /*
   * Constants and data structures used to implement group and password file
   * caches. Traditional passwd/group cache routines perform quite poorly with
   * archives. The chances of hitting a valid lookup with an archive is quite a
   * bit worse than with files already resident on the file system. These misses
   * create a MAJOR performance cost. To address this problem, these routines
   * cache both hits and misses.
   *
   * NOTE:  name lengths must be as large as those stored in ANY PROTOCOL and
   * as stored in the passwd and group files. CACHE SIZES MUST BE PRIME
   */
  let UNMLEN = 32   /* >= user name found in any protocol */
  let GNMLEN = 32   /* >= group name found in any protocol */
  let UID_SZ = 317  /* size of user_name/uid cache */
  let UNM_SZ = 317  /* size of user_name/uid cache */
  let GID_SZ = 251  /* size of gid cache */
  let GNM_SZ = 317  /* size of group name cache */
  let VALID = 1     /* entry and name are valid */
  let INVALID = 2   /* entry valid, name NOT valid */

  var uidtb : [UInt : String] = [:]  // UIDC **uidtb = NULL;	/* uid to name cache */
  var gidtb : [UInt : String] = [:]  // GIDC **gidtb = NULL;	/* gid to name cache */
  var usrtb : [String : UInt] = [:]  // UIDC **usrtb = NULL;	/* user name to uid cache */
  var grptb : [String : UInt] = [:]  //  GIDC **grptb = NULL;	/* group name to gid cache */

  init() {
    setpassent(1)
    setgroupent(1)
  }

  /*
   * name_uid()
   *	caches the name (if any) for the uid. If frc set, we always return the
   *	the stored name (if valid or invalid match). We use a simple hash table.
   * Return
   *	Pointer to stored name (or an empty string).
   */

  func name_uid(_ uid : UInt, _ frc : Bool) -> String {
    /*
     * see if we have this uid cached
     */
    if let ptr = uidtb[uid] {
      if ptr.isEmpty {
        if !frc { return "" }
        else { return String(uid) }
      }
      return ptr
    }

    guard let pw = getpwuid(uid_t(uid)) else {
      uidtb[uid] = ""
      /*
       * no match for this uid in the local password file
       * a string that is the uid in numeric format
       */
      if !frc { return "" }
      else { return String(uid) }
    }
      /*
       * there is an entry for this uid in the password file
       */
    let r = String(cString: pw.pointee.pw_name)
    uidtb[uid] = r
    return r
  }

  /*
   * name_gid()
   *	caches the name (if any) for the gid. If frc set, we always return the
   *	the stored name (if valid or invalid match). We use a simple hash table.
   * Return
   *	Pointer to stored name (or an empty string).
   */

  func name_gid(_ gid : UInt, _ frc : Bool) -> String {
    /*
     * see if we have this gid cached
     */
    if let ptr = gidtb[gid] {
      if ptr.isEmpty {
        if (!frc) { return "" }
        else { return String(gid) }
      }
      return ptr
    }

    guard let gr = getgrgid(gid_t(gid)) else {
      /*
       * no match for this gid in the local group file, put in
       * a string that is the gid in numeric format
       */
      gidtb[gid] = ""
      if !frc { return("") }
      else { return String(gid) }
    }
      /*
       * there is an entry for this group in the group file
       */
    let r = String(cString: gr.pointee.gr_name)
    gidtb[gid]=r
    return r
  }

  /*
   * uid_name()
   *	caches the uid for a given user name. We use a simple hash table.
   * Return
   *	the uid (if any) for a user name, or a -1 if no match can be found
   */

  func uid_name(_ name : String) -> UInt? {

    // return nil for mangled names
    if name.isEmpty { return nil }

    // look up in hash table, if found and valid return the uid
    // if found and invalid, return nil
    if let ptr = usrtb[name] {
      if ptr == UInt.max { return nil }
      return ptr
    }

    // no match, look it up, if no match store it as an invalid entry, or store the matching uid
    guard let pw = getpwnam(name) else {
      usrtb[name]=UInt.max
      return nil
    }
    let r = UInt(pw.pointee.pw_uid)
    usrtb[name]=r
    return r
  }

  /*
   * gid_name()
   *	caches the gid for a given group name. We use a simple hash table.
   * Return
   *	the gid (if any) for a group name, or a -1 if no match can be found
   */

  func gid_name(_ name : String) -> UInt? {
    // return nil for mangled names
    if name.isEmpty { return nil }

    /*
     * look up in hash table, if found and valid return the uid,
     * if found and invalid, return a -1
     */
    if let ptr = grptb[name] {
      if ptr == UInt.max { return nil }
      return ptr
    }

    // no match, look it up, if no match store it as an invalid entry, or store the matching gid
    guard let gr = getgrnam(name) else {
      grptb[name]=UInt.max
      return nil
    }

    let r = UInt(gr.pointee.gr_gid)
    grptb[name]=r
    return r
  }
}
